args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?olderFilm ?olderFilmLabel ?olderDirector ?olderDirectorLabel ?olderBirth ?otherFilm ?otherDirector ?otherDirectorLabel ?otherBirth WHERE {
  VALUES (?filmA ?filmB) { (dbr:The_Galloping_Kid dbr:Parachute_Nurse) (dbr:Parachute_Nurse dbr:The_Galloping_Kid) }
  ?filmA dbo:director ?dirA .
  ?filmB dbo:director ?dirB .
  ?dirA dbo:birthDate ?birthA .
  ?dirB dbo:birthDate ?birthB .
  FILTER(?birthA < ?birthB)
  BIND(?filmA AS ?olderFilm)
  BIND(?dirA AS ?olderDirector)
  BIND(?birthA AS ?olderBirth)
  BIND(?filmB AS ?otherFilm)
  BIND(?dirB AS ?otherDirector)
  OPTIONAL { ?olderFilm rdfs:label ?olderFilmLabel . FILTER(lang(?olderFilmLabel) = "en") }
  OPTIONAL { ?olderDirector rdfs:label ?olderDirectorLabel . FILTER(lang(?olderDirectorLabel) = "en") }
  OPTIONAL { ?otherDirector rdfs:label ?otherDirectorLabel . FILTER(lang(?otherDirectorLabel) = "en") }
}

